    // ===== 等比缩放 =====
    function resizeApp() {
        var app = document.querySelector('.app-container');
        if (!app) return;
        var scale = Math.min(
            window.innerWidth / 1920,
            window.innerHeight / 1080
        );
        app.style.transform = 'translate(-50%, -50%) scale(' + scale + ')';
    }

    window.addEventListener('resize', resizeApp);
    window.addEventListener('DOMContentLoaded', resizeApp);
    resizeApp();

    // ===== 更新顶部标题 =====
    function updateTopTitle(pageId) {
        var titleText = document.getElementById('titleText');
        var gold = document.getElementById('titleSparkleGold');
        var pink = document.getElementById('titleSparklePink');
        var app = document.querySelector('.app-container');
        if (!titleText) return;

        if (pageId === 'page-report') {
            titleText.textContent = PLANETS[currentPlanet] ? PLANETS[currentPlanet].name : '学习星';
            if (gold) gold.style.display = 'none';
            if (pink) pink.style.display = 'none';
            app.classList.add('on-report');
        } else if (pageId === 'page-cards') {
            titleText.textContent = '我的星系';
            if (gold) gold.style.display = '';
            if (pink) pink.style.display = '';
            app.classList.remove('on-report');
        } else if (pageId === 'page-reports') {
            titleText.textContent = '我的星系';
            if (gold) gold.style.display = '';
            if (pink) pink.style.display = '';
            app.classList.remove('on-report');
        } else {
            titleText.textContent = '我的星系';
            if (gold) gold.style.display = '';
            if (pink) pink.style.display = '';
            app.classList.remove('on-report');
        }
    }

    // ===== 页面切换 =====
    function showPage(id) {
        var pages = document.querySelectorAll('.page');
        pages.forEach(function (p) { p.classList.remove('active'); });
        var target = document.getElementById(id);
        if (target) target.classList.add('active');

        var app = document.querySelector('.app-container');
        if (id === 'page-home' || id === 'page-cards' || id === 'page-reports') {
            app.classList.remove('show-back');
        } else {
            app.classList.add('show-back');
        }

        updateTopTitle(id);
        updateNavHighlight(id);
    }

    function updateNavHighlight(pageId) {
        var navItems = document.querySelectorAll('.nav-item');
        navItems.forEach(function (item) {
            item.classList.remove('active');
            var nav = item.getAttribute('data-nav');
            var targetPage = NAV_MAP[nav];
            if (targetPage === pageId) {
                item.classList.add('active');
            }
        });
        // 首页高亮"我的星系"
        if (pageId === 'page-home') {
            var homeNav = document.querySelector('.nav-item[data-nav="home"]');
            if (homeNav) homeNav.classList.add('active');
        }
        // 报告页高亮"我的烦恼"
        if (pageId === 'page-report') {
            var worriesNav = document.querySelector('.nav-item[data-nav="worries"]');
            if (worriesNav) worriesNav.classList.add('active');
        }
    }

