    function setInputPlanet(planetKey) {
        var p = PLANETS[planetKey];
        if (!p) return;
        currentPlanet = planetKey;

        // 星球图标
        var circle = document.getElementById('inputPlanetCircle');
        if (circle) {
            circle.className = 'input-planet-circle ' + p.themeClass;
            circle.innerHTML = p.icon;
        }

        // 星球名称
        var nameEl = document.getElementById('inputPlanetName');
        if (nameEl) nameEl.textContent = p.name;

        // 副标题
        var subtitleEl = document.getElementById('inputSubtitle');
        if (subtitleEl) {
            subtitleEl.textContent = SUBTITLE_MAP[planetKey] || DEFAULT_SUBTITLE;
        }

        // 输入框：预填案例正文 + placeholder
        var input = document.getElementById('worryInput');
        if (input) {
            input.placeholder = '和' + p.name + '说说最近发生的一件烦恼……';
            input.value = p.content || '';
        }
    }

